// Audio for the live-data videos: the kit's cached music bed (Lyria, generated by scripts/src/record-demos-final.mjs
// into .localnet/demo/final/audio) plus a synthesized tick for every on-screen event, levelled and limited, then
// muxed as AAC. The ticks are written sample by sample, so they land on the exact frame their marker pops.
import { execFileSync, spawnSync } from "node:child_process";
import { copyFileSync, existsSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(fileURLToPath(new URL("../../..", import.meta.url)));
const BEDS = join(ROOT, ".localnet/demo/final/audio");
const RATE = 48000;

const run = (args) => execFileSync("ffmpeg", ["-hide_banner", "-loglevel", "error", "-y", ...args], { stdio: ["ignore", "inherit", "inherit"] });
const loudness = (file) => {
  const r = spawnSync("ffmpeg", ["-hide_banner", "-nostats", "-i", file, "-af", "ebur128", "-f", "null", "-"], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  if (r.status !== 0) throw new Error(`ffmpeg failed: ${r.stderr.slice(-800)}`);
  return Number(/I:\s+(-?[\d.]+) LUFS/.exec(r.stderr.slice(r.stderr.lastIndexOf("Summary:")))[1]);
};

/** A cached kit music bed: `bundle` (100 bpm, forward pulse), `explainer` (88 bpm) or `agent` (80 bpm, ambient). */
export function bed(name) {
  const file = join(BEDS, `music-${name}.mp3`);
  if (!existsSync(file)) throw new Error(`${file} missing: run scripts/src/record-demos-final.mjs once to generate the kit's music beds`);
  return file;
}

// Tick voices: a bright two-partial ping for sells, a rounder low one for buys.
const VOICES = {
  sell: { parts: [[1320, 0.55], [2640, 0.15]], decay: 0.03, len: 0.12 },
  buy: { parts: [[440, 0.6], [880, 0.2]], decay: 0.05, len: 0.18 },
};

/**
 * Writes `out` (48 kHz stereo s16 WAV, `total` seconds): one tick per event ({ at: seconds, kind: "sell" | "buy" }),
 * events closer than 50 ms to the previous kept one skipped so dense stretches stay a rhythm, not a buzz.
 */
export function ticks(events, total, out) {
  const n = Math.ceil(total * RATE);
  const buf = new Float32Array(n);
  let last = -1;
  for (const e of [...events].sort((a, b) => a.at - b.at)) {
    if (e.at - last < 0.05) continue;
    last = e.at;
    const v = VOICES[e.kind];
    const i0 = Math.round(e.at * RATE), len = Math.round(v.len * RATE);
    for (let i = 0; i < len && i0 + i < n; i++) {
      const t = i / RATE;
      const env = Math.min(1, t / 0.002) * Math.exp(-t / v.decay);
      let s = 0;
      for (const [f, g] of v.parts) s += g * Math.sin(2 * Math.PI * f * t);
      buf[i0 + i] += 0.35 * env * s;
    }
  }
  const pcm = Buffer.alloc(n * 4);
  for (let i = 0; i < n; i++) {
    const s = Math.round(Math.max(-1, Math.min(1, buf[i])) * 32767);
    pcm.writeInt16LE(s, i * 4);
    pcm.writeInt16LE(s, i * 4 + 2);
  }
  const header = Buffer.alloc(44);
  header.write("RIFF", 0); header.writeUInt32LE(36 + pcm.length, 4); header.write("WAVE", 8);
  header.write("fmt ", 12); header.writeUInt32LE(16, 16); header.writeUInt16LE(1, 20); header.writeUInt16LE(2, 22);
  header.writeUInt32LE(RATE, 24); header.writeUInt32LE(RATE * 4, 28); header.writeUInt16LE(4, 32); header.writeUInt16LE(16, 34);
  header.write("data", 36); header.writeUInt32LE(pcm.length, 40);
  writeFileSync(out, Buffer.concat([header, pcm]));
  return out;
}

/** Music bed (faded, at `musicLufs`) + ticks (at `ticksLufs`) → `out`, limited at −1.5 dBFS. */
export function mix({ music, ticksWav, total, out, musicLufs = -17, ticksLufs = -22 }) {
  const mu = `${out}.music.wav`;
  run(["-t", total.toFixed(3), "-i", music, "-af", `aresample=${RATE},aformat=channel_layouts=stereo,afade=t=in:d=0.6,afade=t=out:st=${(total - 2).toFixed(3)}:d=2`, "-c:a", "pcm_s16le", mu]);
  const muGain = musicLufs - loudness(mu);
  const tkGain = ticksLufs - loudness(ticksWav);
  run(["-i", mu, "-i", ticksWav, "-filter_complex", `[0:a]volume=${muGain.toFixed(2)}dB[m];[1:a]volume=${tkGain.toFixed(2)}dB[t];[m][t]amix=inputs=2:normalize=0,alimiter=limit=0.84:level=false[o]`, "-map", "[o]", "-ar", String(RATE), "-c:a", "pcm_s16le", out]);
  rmSync(mu);
  return out;
}

/** Muxes `audio` into `video` in place (AAC 192 kb/s, video stream copied, cut to the shorter). */
export function mux(video, audio) {
  const tmp = `${video}.tmp.mp4`;
  run(["-i", video, "-i", audio, "-map", "0:v", "-map", "1:a", "-c:v", "copy", "-c:a", "aac", "-b:a", "192k", "-shortest", "-movflags", "+faststart", tmp]);
  copyFileSync(tmp, video);
  rmSync(tmp);
}
